import{_ as h}from"./chunks/namhoa.0vN8z-jB.js";import{_ as a,o as i,c as t,a1 as r}from"./chunks/framework.DK3UFCr3.js";const m=JSON.parse('{"title":"Khoe hình","description":"","frontmatter":{"layout":"doc","author":"Nhieu Tac Gia","title":"Khoe hình"},"headers":[],"relativePath":"khoehinh.md","filePath":"khoehinh.md"}'),o={name:"khoehinh.md"};function e(c,n,s,g,u,b){return i(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="khoe-hinh" tabindex="-1">Khoe hình <a class="header-anchor" href="#khoe-hinh" aria-label="Permalink to &quot;Khoe hình&quot;">​</a></h1><p><em>Tác giả: Nhieu Tác Giả</em></p><p>Ví dầu cầu ván đóng đinh,<br> Có thằng Trực Kẽm có hình muốn khoe.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><br> Muốn khoe mà hổng chịu khoe,<br> Có người đổ quạu rồi nè Kẽm ơi.<br> Sáng trăng Nam tưởng tối trời<br> Ngồi đâu lại để lưng phơi ra ngoài.<br> Cái lưng, đầu tóc,,, ngời ngời<br> Tưởng ai cũng xỉn, có người đô cao.<br> Trên trời có triệu vì sao,<br> Ngồi nhai bắp cháy hồn nào chẳng say.<br> Bập bùng bếp lửa khói bay.<br> Tàu dừa e thẹn, bắp đầy muội than.<br> Khổ công tuyển lựa bắp non,<br> Bạn Huyền, bạn Hiếu, bạn Loan đau lòng.<br> Bắp khoai nướng ngọn lửa hồng,<br> Loan đừng ăn nữa uổng công tu hành.<br> Tàu dừa phơn phớt gió đàn,<br> Vầng trăng chia nửa, tim vàng ghép đôi.<br> Thời gian như đã ngừng trôi,<br> Thanh xuân rực rỡ một thời có nhau.<br> Gặp nhau ngồi kế bên nhau,<br> Chia tay say nắng cảm sầu hai nơi.</p><p><img src="'+h+'" alt=""></p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ca dao<br> Ví dầu cầu ván đóng đinh.<br> Cầu tre lắt lẻo gập ghình khó đi.<br> Khó đi mẹ dắt con đi.<br> Con đi trường học. Mẹ đi trường đời. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',6)])])}const f=a(o,[["render",e]]);export{m as __pageData,f as default};
